import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

type Row = { label: string; value: number };

const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : 0;
};

const str = (v: unknown, fallback: string): string =>
  typeof v === "string" && v.trim().length > 0 ? v.trim() : fallback;

const readRows = (raw: unknown, max: number): Row[] => {
  if (!Array.isArray(raw)) return [];
  return raw
    .map((item) => {
      const o = (item ?? {}) as Record<string, unknown>;
      return { label: str(o.label, ""), value: num(o.value) };
    })
    .filter((r) => r.label !== "" || r.value > 0)
    .slice(0, max);
};

const PayPerViewRanking: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;

  // landscape lays the niches out as columns across the width; portrait/half stack bars.
  const columns = format === "landscape";
  const compact = format === "half";

  const s = columns ? frame.height / 1080 : compact ? frame.height / 960 : frame.width / 1080;
  const px = (v: number) => v * s;

  const T = compact
    ? { pad: 38, gap: 14, title: 44, eyebrow: 14, label: 20, value: 34, bar: 16, pill: 17, radius: 12 }
    : columns
    ? { pad: 70, gap: 24, title: 66, eyebrow: 19, label: 24, value: 44, bar: 20, pill: 21, radius: 16 }
    : { pad: 64, gap: 26, title: 78, eyebrow: 22, label: 30, value: 54, bar: 26, pill: 25, radius: 18 };

  const rows = readRows(p.rows, compact ? 3 : 5);
  const prefix = typeof p.prefix === "string" ? p.prefix : "";
  const suffix = typeof p.suffix === "string" ? p.suffix : "";
  const eyebrow = str(p.eyebrow, "");
  const headline = str(anim.text, "");
  const note = str(p.note, "");

  const max = rows.reduce((a, r) => Math.max(a, r.value), 0);
  const winnerParam = typeof p.winner === "string" ? p.winner.trim().toLowerCase() : "";
  const named = rows.findIndex((r) => r.label.trim().toLowerCase() === winnerParam);
  const byValue = rows.reduce((best, r, i) => (r.value > rows[best].value ? i : best), 0);
  const winner = rows.length === 0 ? -1 : named >= 0 ? named : byValue;

  const runnerUp = rows.reduce((best, r, i) => (i !== winner && r.value > best ? r.value : best), 0);
  const multiplier = winner >= 0 && runnerUp > 0 ? rows[winner].value / runnerUp : 0;

  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  // long labels shrink instead of getting cut; they also wrap freely
  const longest = rows.reduce((a, r) => Math.max(a, r.label.length), 0);
  const labelSize =
    px(T.label) * Math.max(0.66, Math.min(1, (columns ? 13 : 20) / Math.max(1, longest)));

  const decimals = (v: number) => (Number.isInteger(v) ? 0 : 2);
  const money = (v: number, d: number) => `${prefix}${v.toFixed(d)}${suffix}`;

  const titleIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.7 } });
  const barStart = 12;
  const stagger = 7;
  const barDur = 26;
  const settled = barStart + Math.max(0, rows.length - 1) * stagger + barDur;
  const grow = (i: number) =>
    interpolate(f, [barStart + i * stagger, barStart + i * stagger + barDur], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    });
  const crown = Math.min(1, spring({ frame: f - settled, fps, config: { damping: 12, mass: 0.6 } }));
  const out = interpolate(f, [total - 8, total - 1], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const barFill = (isWinner: boolean, dir: string) =>
    isWinner ? headlineGradient() : `linear-gradient(${dir}, ${COLORS.leather}, ${COLORS.leather}99)`;

  const valueBlock = (i: number) => {
    const r = rows[i];
    const isWinner = i === winner;
    const d = decimals(r.value);
    return (
      <div style={{ display: "flex", alignItems: "baseline", gap: px(8), flexShrink: 0 }}>
        <span
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: px(T.value) * (isWinner ? 1 : 0.82),
            lineHeight: 0.95,
            whiteSpace: "nowrap",
            fontVariantNumeric: "tabular-nums",
            ...(isWinner
              ? {
                  backgroundImage: headlineGradient(),
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  color: "transparent",
                }
              : { color: muted, textShadow: ENGRAVE_SHADOW }),
          }}
        >
          {money(r.value * grow(i), d)}
        </span>
        {isWinner && multiplier > 1 ? (
          <span
            style={{
              fontFamily: FONTS.body,
              fontWeight: 700,
              fontSize: px(T.pill),
              lineHeight: 1,
              padding: `${px(5)}px ${px(10)}px`,
              borderRadius: 999,
              whiteSpace: "nowrap",
              color: COLORS.tealBright,
              background: `${COLORS.teal}1F`,
              border: `1px solid ${COLORS.teal}66`,
              opacity: crown,
              transform: `scale(${0.7 + 0.3 * crown})`,
            }}
          >
            {multiplier.toFixed(1)}\u00d7
          </span>
        ) : null}
      </div>
    );
  };

  const labelText = (i: number, align: "left" | "center") => (
    <span
      style={{
        fontFamily: FONTS.body,
        fontWeight: i === winner ? 700 : FONTS.bodyWeight,
        fontSize: labelSize,
        lineHeight: 1.2,
        letterSpacing: "0.02em",
        color: i === winner ? txt : muted,
        textAlign: align,
        minWidth: 0,
        overflowWrap: "break-word",
      }}
    >
      {rows[i].label}
    </span>
  );

  const barRows = (
    <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: px(T.gap) }}>
      {rows.map((r, i) => {
        const isWinner = i === winner;
        const prog = grow(i);
        const width = max > 0 ? (r.value / max) * 100 * prog : 0;
        return (
          <div
            key={`row-${i}`}
            style={{
              display: "flex",
              flexDirection: "column",
              gap: px(8),
              opacity: interpolate(prog, [0, 0.2], [0, 1], { extrapolateRight: "clamp" }),
              transform: `translateY(${(1 - prog) * px(14)}px)`,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                justifyContent: "space-between",
                gap: px(14),
              }}
            >
              {labelText(i, "left")}
              {valueBlock(i)}
            </div>
            <div
              style={{
                height: px(T.bar),
                borderRadius: 999,
                background: "rgba(255,255,255,0.08)",
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  width: `${width}%`,
                  height: "100%",
                  borderRadius: 999,
                  backgroundImage: barFill(isWinner, "90deg"),
                  boxShadow: isWinner
                    ? `0 0 ${px(22)}px ${COLORS.teal}${crown > 0.5 ? "77" : "33"}`
                    : "none",
                }}
              />
            </div>
          </div>
        );
      })}
    </div>
  );

  const barColumns = (
    <div
      style={{
        flex: 1,
        width: "100%",
        display: "flex",
        alignItems: "stretch",
        justifyContent: "center",
        gap: px(T.gap),
        minHeight: px(200),
      }}
    >
      {rows.map((r, i) => {
        const isWinner = i === winner;
        const prog = grow(i);
        const height = max > 0 ? (r.value / max) * 100 * prog : 0;
        return (
          <div
            key={`col-${i}`}
            style={{
              flex: 1,
              minWidth: 0,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: px(10),
              opacity: interpolate(prog, [0, 0.2], [0, 1], { extrapolateRight: "clamp" }),
            }}
          >
            {valueBlock(i)}
            <div
              style={{
                flex: 1,
                width: "100%",
                display: "flex",
                alignItems: "flex-end",
                justifyContent: "center",
              }}
            >
              <div
                style={{
                  width: "66%",
                  height: `${height}%`,
                  borderRadius: px(T.radius),
                  backgroundImage: barFill(isWinner, "0deg"),
                  boxShadow: isWinner
                    ? `0 0 ${px(30)}px ${COLORS.teal}${crown > 0.5 ? "66" : "33"}`
                    : "none",
                }}
              />
            </div>
            {labelText(i, "center")}
          </div>
        );
      })}
    </div>
  );

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: px(T.pad),
        gap: px(compact ? 14 : 24),
        opacity: out,
      }}
    >
      {eyebrow !== "" || headline !== "" ? (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: px(8),
            opacity: titleIn,
            transform: `translateY(${(1 - titleIn) * px(-22)}px)`,
          }}
        >
          {eyebrow !== "" ? (
            <div
              style={{
                fontFamily: FONTS.body,
                fontWeight: 600,
                fontSize: px(T.eyebrow),
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                textAlign: "center",
                color: muted,
              }}
            >
              {eyebrow}
            </div>
          ) : null}
          {headline !== "" ? (
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: px(T.title),
                lineHeight: 0.94,
                textTransform: "uppercase",
                textAlign: "center",
                maxWidth: columns ? "84%" : "96%",
                backgroundImage: headlineGradient(),
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }}
            >
              {headline}
            </div>
          ) : null}
        </div>
      ) : null}

      {rows.length > 0 ? (columns ? barColumns : barRows) : null}

      {note !== "" ? (
        <div
          style={{
            fontFamily: FONTS.body,
            fontWeight: 600,
            fontSize: px(T.eyebrow),
            letterSpacing: "0.14em",
            textTransform: "uppercase",
            textAlign: "center",
            color: muted,
            opacity: crown,
          }}
        >
          {note}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default PayPerViewRanking;
